from taf.ul.sc import perf
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.tc.tc_helpers import get_absolute_path
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console, log_info_to_console
from taf.ul.ue.sim.env_setup import env_setup  # type: ignore
from moler.util.moler_test import MolerTest  # type: ignore
from taf.ul.sc.epcsim.exceptions import ConfigurationFileException  # type: ignore
import os


@log_debug_function_info()
def prepare_bts():
    swconfig_reboot_required = None
    commissioning_types = None

    if tc.is_feature_enabled("bts_preparation->change_swconfig"):
        swconfig_reboot_required = _change_swconfig_file()
    if tc.is_feature_enabled("bts_preparation->perform_commissioning"):
        commissioning_types = _perform_bts_commissioning()

    if _is_reboot_required(swconfig_reboot_required, commissioning_types):
        _reboot_all_sites()

    _activate_ne3s()

    _wait_for_all_sites_response()

    if tc.is_feature_enabled("bts_preparation->set_debug_flags"):
        _set_debug_flags()

    if tc.is_feature_enabled("collect_bts_stats") and tc.run_params['collect_bts_stats']['type'] == 'rtpm':
        _activate_rtpm_reporting()


@log_debug_function_info()
def prepare_ue():
    if tc.is_feature_enabled("ue_preparation->reconfigure"):
        if perf.tl.ue.is_scenario_running():
            perf.tl.ue.stop_scenario()
        _upload_ue_db()
        _upload_ue_cap()
        _change_ue_configuration()


@log_debug_function_info()
def prepare_core():
    if tc.is_feature_enabled("core_preparation->restart"):
        perf.tl.core.restart()
    if tc.is_feature_enabled("core_preparation->reconfigure"):
        config_file_path = get_absolute_path(tc.run_params['core_preparation']['reconfigure']['config_file'])
        require_files = tc.run_params['core_preparation']['reconfigure']['require_files']
        require_files_path = [get_absolute_path(require_file) for require_file in require_files]

        if _check_if_epcsim_configuration_needed(config_file_path=config_file_path, required_files=require_files_path):
            perf.tl.core.change_configuration_file(config_file=config_file_path,
                                                   required_files=require_files_path)
        else:
            MolerTest.info(msg="Configuration skipped. Current config files are the same.")
            if perf.tl.core.egate.get_state()['STATE'] not in ['ACTIVE', 'ACTIVATING']:
                perf.tl.core.change_configuration_file(config_file=config_file_path,
                                                       required_files=require_files_path)

    if tc.is_feature_enabled("core_preparation->configure_console_prints"):
        _configure_console_prints()


def _configure_console_prints():
    params_list = []
    params = tc.run_params['core_preparation']['configure_console_prints']['params']
    if isinstance(params, str):
        params_list.append(params)
    elif isinstance(params, list):
        params_list = params

    for param in params_list:
        perf.tl.core.configure_console_prints(param)


@log_function_status_to_console(msg="Environment preparation with configurator", log_hierarchy=2)
@log_debug_function_info()
def prepare_with_configurator():
    # currently supports only one eNB
    # TODO: add support for multiple eNBs
    MolerTest.info("Using configurator to prepare environment. OAM_TYPE parameter is skipped")
    configurator = env_setup()
    _add_bts_to_configurator(configurator)
    # add simulator configuration
    _add_simulator_to_configurator(configurator)
    # add EPC configuration
    _add_epc_to_configurator(configurator)
    # TO DO: make print failing without it only being a warning not error
    if tc.is_feature_enabled("core_preparation->configure_console_prints"):
        _configure_console_prints()


def _change_cus_configuration_file(config_file, config_file_dir):
    perf.tl.ue.ws.change_configuration_file(config_file=config_file, config_dir=config_file_dir)


def _add_bts_to_configurator(configurator):
    commissioning_types = {}
    MolerTest.info(msg=f"{tc.run_params['bts_preparation']['perform_commissioning']}")
    commissioning_params = tc.run_params['bts_preparation']['perform_commissioning']['params']
    # TODO: add support for reconfiguration if possible
    for bts_name in commissioning_params:
        commissioning_types[bts_name] = 'full'
        path_to_commissioning_file = commissioning_params[bts_name]
        MolerTest.info(f"Adding commissioning configuration from {path_to_commissioning_file}")
        log_info_to_console(msg="Configuring BTS")
        configurator.add_enb_configuration(scfc=path_to_commissioning_file)


def _add_epc_to_configurator(configurator):
    try:
        epc_params = tc.run_params['core_preparation']["reconfigure"]["config_file"]
        epc_path = get_absolute_path(epc_params)
        MolerTest.info(f"Adding EPC configuration from {epc_path}")
        configurator.add_epc(config=epc_path)
        log_info_to_console(msg="Configuring EPC")
        log_info_to_console(msg="Configuring environment")
        configurator.configure_environment()
    except KeyError as e:
        MolerTest.warning(f"EPC configuration not found. Reason: {e}")


def _add_simulator_to_configurator(configurator):
    try:
        simulator_params = tc.run_params['ue_preparation']["reconfigure"]["params"]
        simulator_path = get_absolute_path(simulator_params)
        sim_dir, sim_file = os.path.split(simulator_path)
        MolerTest.info(f"Change config file {sim_file} in {sim_dir}")
        _change_cus_configuration_file(sim_file, sim_dir)
        MolerTest.info(f"Adding simulator configuration from {simulator_path}")
        configurator.add_simulator(sim_type="cus", config=simulator_path)
        log_info_to_console(msg="Configuring CUS")
    except KeyError as e:
        MolerTest.warning(f"Simulator configuration not found. Reason: {e}")


def _perform_bts_commissioning():
    commissioning_types = {}
    commissioning_params = tc.run_params['bts_preparation']['perform_commissioning']['params']
    for bts_name in commissioning_params:
        bts = perf.tl.get_bts(name=bts_name)
        oam_type = _get_proper_oam_type(bts_name)
        if isinstance(commissioning_params[bts_name], list):
            commissioning_types[bts_name] = 'reconfiguration'
            bts.perform_recommissioning(params=commissioning_params[bts_name],
                                        method_type=oam_type)
        else:
            commissioning_types[bts_name] = 'full'
            path_to_commissioning_file = get_absolute_path(commissioning_params[bts_name])
            bts.perform_full_commissioning(commissioning_file=path_to_commissioning_file,
                                           wait_for_on_air=True,
                                           method_type=oam_type)

    return commissioning_types


@log_function_status_to_console(msg="Change swconfig", log_hierarchy=2)
@log_debug_function_info()
def _change_swconfig_file():
    reboot_required = []
    remove_swconfig = False
    path_to_swconfig = None
    swconfig_md5sum = None

    swconfig_file = tc.run_params['bts_preparation']['change_swconfig']['swconfig_file']
    if swconfig_file:
        path_to_swconfig = get_absolute_path(swconfig_file)
        swconfig_md5sum = perf.tl.unix_local.get_md5sum(path_to_swconfig)
    else:
        remove_swconfig = True

    for bts in tc.required_btss():
        new_configuration_applied = bts.change_swconfig(swconfig_file=path_to_swconfig,
                                                        swconfig_md5sum=swconfig_md5sum,
                                                        remove_swconfig=remove_swconfig)
        reboot_required.append(new_configuration_applied)

    return reboot_required


def _is_reboot_required(swconfig_reboot_required, commissioning_types):
    reboot_required = False
    if swconfig_reboot_required:
        reboot_required = any(swconfig_reboot_required)
    if commissioning_types:
        if 'full' in commissioning_types.values():
            reboot_required = False

    return reboot_required


@log_function_status_to_console(msg="Set debug flags via AASHELL", log_hierarchy=2)
@log_debug_function_info()
def _set_debug_flags():
    swconfig_params = tc.run_params['bts_preparation']['set_debug_flags']['params']
    for bts in tc.required_btss():
        bts.bts.change_swconfig_via_aashell(params=swconfig_params)


def _activate_ne3s():
    for bts in tc.required_btss():
        if getattr(bts, 'ems', None):
            bts.ems.cli.activate_ne3s()


def _activate_rtpm_reporting():
    for bts in tc.required_btss():
        if getattr(bts, 'ems', None):
            bts.ems.cli.activate_rtpm_reporting()


def _get_proper_oam_type(bts_name):
    oam_type = tc.run_params['bts_preparation']['perform_commissioning']['oam_type']
    if isinstance(oam_type, dict):
        return oam_type[bts_name]
    else:
        return oam_type


@log_function_status_to_console(msg="Rebooting BTS after applied new configuration", log_hierarchy=2)
@log_debug_function_info()
def _reboot_all_sites():
    for bts in tc.required_btss():
        bts.bts.reboot()


def _wait_for_all_sites_response():
    for bts in tc.required_btss():
        bts.waiting_for_site_response()


def _change_ue_configuration():
    configuration_params = tc.run_params['ue_preparation']['reconfigure']['params']
    if isinstance(configuration_params, dict):
        perf.tl.ue.change_configuration(configuration_params)
    else:
        path_to_configuration_file = get_absolute_path(configuration_params)
        perf.tl.ue.change_configuration_file(path_to_configuration_file)
    if perf.tl.ue.is_rf_cell_in_configuration():
        perf.tl.ue.align_rtg_cell_to_radio_cell()



def _upload_ue_db():
    ue_db = tc.run_params['ue_preparation']['reconfigure']['ue_db']
    if ue_db:
        ue_db_path = get_absolute_path(ue_db)
        perf.tl.ue.upload_ue_db(ue_db_file=ue_db_path)


def _upload_ue_cap():
    ue_cap = tc.run_params['ue_preparation']['reconfigure']['ue_cap']
    if ue_cap:
        ue_caps = ue_cap if isinstance(ue_cap, list) else [ue_cap]
        ue_caps_paths = [get_absolute_path(_ue_cap) for _ue_cap in ue_caps]
        perf.tl.ue.upload_ue_cap(ue_cap_file=ue_caps_paths)


def _check_if_epcsim_configuration_needed(config_file_path, required_files):
    is_needed = False
    config_file_name = os.path.basename(config_file_path)
    config_file_md5sum = perf.tl.unix_local.get_md5sum(config_file_path)

    try:
        current_config_file = perf.tl.core.ws.get_current_config_file_info()
    except ConfigurationFileException:
        return True

    if current_config_file is None or config_file_name != current_config_file['name'] or\
            config_file_md5sum != current_config_file['md5sum']:
        return True
    if required_files is not None:
        return __check_required_files(current_config_file, required_files)

    return is_needed


def __check_required_files(current_config_file, required_files):
    for required_file in required_files:
        required_file_name = os.path.basename(required_file)
        md5sum = perf.tl.unix_local.get_md5sum(required_file)
        if required_file_name not in current_config_file['require_files'].keys() or \
                str(md5sum) != str(current_config_file['require_files'][required_file_name]['md5sum']):
            return True

    return False
